function e(e){let t=0,n=0;for(let r of e)r.kind===`income`?n+=r.amount_cents:r.kind===`expense`&&(t+=r.amount_cents);return{expenseCents:t,incomeCents:n,balanceCents:n-t}}function t(e){return new Intl.NumberFormat(`zh-CN`,{minimumFractionDigits:2,maximumFractionDigits:2}).format(e/100)}function n(e){let t=[];for(let n of e){let e=new Date(n.occurred_at),r=`${e.getFullYear()}-${String(e.getMonth()+1).padStart(2,`0`)}-${String(e.getDate()).padStart(2,`0`)}`,i=t.find(e=>e.date===r);i?i.rows.push(n):t.push({date:r,rows:[n]})}return t}export{n,e as r,t};